    [6] = {s = {["|1"] = "You need to wait 8 real life hours after completing The Clue before this quest is offered.", ["|2"] = "Speak to Rycharde who asks you to take Mhauran couscous to Valgeir in Selbina.", ["|3"] = "Speak to Valgeir in Selbina.", ["|4"] = "Return to Rycharde and trade him the Popoto to complete this quest.", ["|5"] = "You will receive a Tea Set as a reward.", ["|6"] = "(Optional) Speak to Valgeir in Selbina.", ["|7"] = "(Optional) Speak to Rycharde one last time to conclude the questline."}},
