    [9] = {s = {["|1"] = "Speak to Nereus (I-8) near the Proto-Waypoint to begin this quest.", ["|2"] = "Go to I-7 (third map) in Gusgen Mines, near a pond, and click on the \"Clay\" to obtain Gusgen Clay:", ["|3"] = "Bring the Gusgen Clay back to Nereus to complete the quest.", ["|4"] = "You must wait 8 hours before repeating this quest."}},
