    [19] = {s = {["|1"] = "Talk to Abelard (G-9) to receive Selbina Clay.", ["|2"] = "Trade the Selbina Clay to a Stone Monument to receive a Clay Tablet.", ["|3"] = "Return to Abelard and trade the Clay Tablet to him.", ["|4"] = "Repeat for the remaining Stone Monuments."}},
    [20] = {s = {["|1"] = "Talk to Vuntar (H-9) in Selbina.", ["|2"] = "Purchase some Rolanberries.", ["|3"] = "Proceed to Crawler's Nest to turn your Rolanberries into higher-quality Rolanberries.", ["|4"] = "Bring the rolanberries that drop from the crawlers back to Vuntar for your reward."}},
