    [23] = {s = {["|1"] = "Speak to Thunder Hawk to begin the quest.", ["|2"] = "Head to Beadeaux and kill De'Vyu Headhunter to obtain a Quadav Charm.", ["|3"] = "Head to (I-8) and trade the Quadav Charm to the Jail Door (on the ground floor) for a cinematic experience and a Trader's sack.", ["|4"] = "Return to Thunder Hawk for a storytelling scene your reward."}},
    [25] = {s = {["|1"] = "Speak to Devean who will ask you to bet on how long it takes you to get a pair of Power Sandals from Davoi.", ["|2"] = "Once in Davoi you need to locate a Jar that contains the Power Sandals.", ["|3"] = "Return the Power Sandals to Devean before time runs out.", ["|4"] = "You can also choose to keep the Power Sandals for yourself."}},
    [26] = {s = {["|1"] = "Have 30 fishing skill or greater, including temporary boosts from either gear or image support, and talk to Zaldon.", ["|2"] = "Trade Zaldon certain fish and he will gut them for you.", ["|3"] = "He will buy the fish that you trade for a fixed price, as well as give you anything that might be in its stomach.", ["|4"] = "As of the November 10th, 2021 Version Update, the chance to receive an item is increased when a bigger fish is traded.", ["|5"] = "Note: After completing the quest for the first time, you no longer need to meet the fishing level requirement to repeat the quest."}},
    [27] = {s = {["|1"] = "Speak with Ripapa to obtain the quest.", ["|2"] = "Travel to The Sanctuary of Zi'Tah enter to The Boyahda Tree at (K-12) or (J-12).", ["|3"] = "Defeat Ramuh Prime and you will receive a key item: Whisper of storms", ["|4"] = "Return to Ripapa with the whisper and she will provide several reward options including the ability to summon Ramuh (Avatar)."}},
    [28] = {s = {["|1"] = "Speak with Lacia in Mhaura (I-9) to begin quest and obtain a Mini Tuning Fork of Lightning.", ["|2"] = "You may prepare for the upcoming battle and whenever you are ready, trade Lacia the tuning fork to be transported to the arena.", ["|3"] = "Trade the fork to the Lightning Protocrystal to enter the fighting arena.", ["|4"] = "Defeat Ramuh Prime to complete quest."}},
    [29] = {s = {["|1"] = "Speak to Fyi Chalmwoh in Mhaura at (G-8) to begin the quest, then speak to her again.", ["|2"] = "Speak to Ramona in Selbina at (H-9) to receive Ye Olde Mannequin Catalogue.", ["|3"] = "Speak to Cheupirudaux in Northern San d'Oria HP #4 at (F-3) to receive Mannequin joint diagrams.", ["|4"] = "Gather all 5 Mannequin pieces and trade them to Fyi Chalmwoh.", ["|5"] = "Zone and speak to Fyi Chalmwoh again to receive your reward."}},
    [30] = {s = {["|1"] = "Speak to Keshab-Menjab at the lower level of (H-9) in Mhaura.", ["|2"] = "Head to Bibiki Bay - Purgonorgo Isle and fish up a Lancet Jagil.", ["|3"] = "Defeat Lancet Jagils to obtain a Cleanly Snapped Rod.", ["|4"] = "Return the rod to Keshab-Menjab to complete the quest."}},
    [32] = {s = {["|1"] = "Speak to Carbuncle at the ???", ["|10"] = "You must wait until the Conquest Tally is updated for the week before you can repeat this quest.", ["|11"] = "1. Defeat the Carbuncles and Celestial Avatars up until the 3 Celestial Avatars pop.", ["|12"] = "2. Defeat two of the three Celestial Avatars.", ["|13"] = "3. Bring the last Celestial Avatar down to about 10% without using Blood Pact: Rages.", ["|14"] = "4. At this point, one Summoner should Astral Flow and use Alexander.", ["|15"] = "5. After Alexander is finished, quickly siphon more MP while the other Summoner kills the last Celestial Avatar using Avatar melee only.", ["|16"] = "6. When the 5 Carbuncle Primes spawn, each Summoner should take one and kill it with a Blood Pact.", ["|17"] = "7. This leaves 3 Carbuncle Primes left and removes the danger of the Searing Light that they spam.", ["|2"] = "You must collect six key items dropped from six battles against much harder versions of the 6 Celestial avatars.", ["|3"] = "Each battle takes place at the avatar's respective Cloister.", ["|4"] = "Once you have obtained all six key items, proceed to Full Moon Fountain for a cutscene and the last Battle.", ["|5"] = "The six key items are not lost upon defeat, but lost upon winning the fight.", ["|6"] = "During the cutscene you are given a choice to return the Faded ruby to Carbuncle.", ["|7"] = "Return to the ???", ["|8"] = "Every player who participates in the final fight will receive a Carbuncle's Pole after finishing the quest in La Theine Plateau.", ["|9"] = "All other quest rewards are randomly dropped at the end of the Carbuncle Prime battle."}},
    [34] = {s = {["|1"] = "Speak to the Suspicious Hume in Pashhow Marshlands (E-12).", ["|2"] = "He will ask you to acquire one of three items: Rabbit Hide, Lizard Tail, or Two-Leaf Mandragora Bud.", ["|3"] = "Procure one of the items and trade it to any of the following NPCs: Suspicious Tarutaru in Port Windurst (M-4) near Home Point #3 (M).", ["|4"] = "After a brief cutscene you are given the Ring of supernal disjunction.", ["|5"] = "Examine the Odyssean Passage and enter to receive a cutscene completing the quest.", ["|6"] = "To obtain Gladiatorial writ of summons for the quest The Curious Case of Melvien, speak to Suspicious Tarutaru, Suspicious Elvaan or"}},
    [64] = {s = {["|1"] = "Talk to Quelveuiat.", ["|2"] = "Zone into Lufaise Meadows by taking the south exit at (I-6).", ["|3"] = "Head to (H-10) afterwards.", ["|4"] = "Click the ??? at the top of the platform to spawn Splinterspine Grukjuk, a Ranger Orc NM.", ["|5"] = "Return to Tavnazian Safehold and speak with Quelveuiat to complete the quest.", ["|6"] = "After completing the quest you may trade Quelveuiat a Sealion Crest Key and a Coral Crest Key to obtain a Temple Knight key."}},
    [65] = {s = {["|1"] = "Talk to Despachiaire (K-10 Upper Level) behind the Walnut Door at (K-9) to start the quest.", ["|11"] = "Return to Odeya for the next cutscene and your reward.", ["|2"] = "Talk to Parelbriaux.", ["|3"] = "Talk to Odeya.", ["|4"] = "Obtain a Tavnazian Liver from the Orcs in Lufaise Meadows or the Tavnazian Sheep in Lufaise Meadows or Misareaux Coast.", ["|5"] = "Return to Tavnazian Safehold and trade the Tavnazian Liver to Odeya.", ["|6"] = "Proceed to Phomiuna Aqueducts:"}},
    [66] = {s = {["|1"] = "Talk to Frescheque (H-8, 3rd floor)", ["|2"] = "Talk to Raminey.", ["|3"] = "Talk to Equette (I-9, 2nd floor)", ["|4"] = "Go to Lufaise Meadows and click on the ??? at (I-8) to spawn two Orc NMs:", ["|5"] = "Defeat the NMs and select ??? again to obtain Tiny wristlet.", ["|6"] = "Return to the Tavnazian Safehold and talk to Frescheque for your reward.", ["|7"] = "Talk to Equette again for an additional cutscene."}},
    [67] = {s = {["|1"] = "Speak to Leporaitceau (J-8) in the underground of the 3rd floor.", ["|2"] = "Speak to Equette (I-9) on the 2nd floor near the bottom of the ramp.", ["|3"] = "Speak to Anteurephiaux (J-8) on the 3rd floor near Leporaitceau to officially begin this quest.", ["|4"] = "Travel to Misareaux Coast and look for a ??? at (K-12).", ["|5"] = "Checking the ??? will spawn the NM Bloody Coffin.", ["|6"] = "Once the NM is defeated, check the ??? again for the Whispering conch.", ["|7"] = "Return to Anteurephiaux.", ["|8"] = "Finally, speak to Equette to complete this quest."}},
    [68] = {s = {["|1"] = "Talk to Nivorajean (I-9) to flag the quest.", ["|2"] = "Go to Sacrarium and obtain a Sacrarium Chest Key", ["|3"] = "Locate the position of a Treasure Chest, making sure to note the location.", ["|4"] = "Open the Treasure chest to obtain Piece of Ripped Floorplans", ["|5"] = "Return to Nivorajean and talk to him", ["|6"] = "Select the position of the chest that you found your Piece of Ripped Floorplans.", ["|7"] = "If you selected correctly, then he will provide you with your reward after midnight (next game day)."}},
    [69] = {s = {["|1"] = "To activate this quest you must be on or past Promathia Mission 4-2 and have zoned into Riverne - Site B01.", ["|2"] = "Speak to Epinolle to begin this quest.", ["|3"] = "Enter Riverne - Site B01.", ["|4"] = "Once inside, head to the island at (J-6).", ["|5"] = "As soon as you exit the spatial distortion that brought you to the island, three NM's will spawn.", ["|6"] = "Return to Epinolle after you've defeated the NM's."}},
    [70] = {s = {["|1"] = "Speak to Travonce in Tavnazian Safehold at (F-9).", ["|10"] = "Speak to Travonce in Tavnazian Safehold at (F-9) for your reward.", ["|11"] = "He fishes up the following monsters during this quest.", ["|2"] = "Zone out of the Safehold into Lufaise Meadows (Southeast Exit) between 13:00-16:00.", ["|3"] = "Do not talk to Travonce until all party members are in the area.", ["|4"] = "His first stop will be on the bridge.", ["|5"] = "He will then head to the sea.", ["|6"] = "Kill any more Notorious Monsters he fishes up.", ["|7"] = "Eventually he moves on to a lake to the north.", ["|8"] = "He will fish up three more Notorious Monsters.", ["|9"] = "He will eventually fish up The Big One, which is a Flesh monster."}},
    [71] = {s = {["|1"] = "Speak to Ferchinne at (G-9) to begin this quest.", ["|2"] = "Trade Ferchinne two Hippogryph Tailfeathers to complete this quest.", ["|3"] = "Mistmelts are able to force Ouryu out of the sky and on to the ground when fighting him.", ["|4"] = "Has no effect in The Savage II."}},
    [72] = {s = {["|1"] = "Speak to Elysia (first floor, G-10) to begin this quest.", ["|2"] = "Head up to the third floor of the safehold and examine the ??? behind the pillar at (K-9) near the Walnut Door. (you may need to examine it", ["|3"] = "Return to Elysia.", ["|4"] = "Speak to Pradiulot (H-9).", ["|5"] = "For an additional cutscene that continues the storyline, return to Elysia once more and then speak to Pradiulot."}},
    [73] = {s = {["|1"] = "Talk to Despachiaire in Tavnazian Safehold at (K-10), top floor.", ["|2"] = "Talk to Jonette on the middle floor near the stream at (G-9).", ["|3"] = "Phomiuna Aqueducts Walkthrough:", ["|4"] = "Sacrarium Walkthrough:", ["|5"] = "Repeating the Quest: The quest can be repeated once every conquest week."}},
    [74] = {s = {["|1"] = "Speak to Chemioue on the top floor at (J-6) for a cutscene.", ["|2"] = "Speak to Tressia, next to Chemioue.", ["|3"] = "Speak to Parelbriaux (K-7).", ["|4"] = "Speak to Ondieulix (I-7), middle floor, for a cutscene.", ["|5"] = "Head to Lufaise Meadows and look for a ??? at (G-6).", ["|6"] = "The ??? will spawn the NM Baumesel but only during foggy weather.", ["|7"] = "Once the NM is defeated, check the ??? again and return to Ondieulix for your reward."}},
    [75] = {s = {["|1"] = "Speak to Despachiaire for a cutscene and to receive Antique amulet.", ["|2"] = "Head to Southern San d'Oria and speak to Rouva (I-8).", ["|3"] = "Travel to Carpenters' Landing via the Jugner Forest (E-6) entrance.", ["|4"] = "Check the ??? at (F-9) to spawn an NM Para.", ["|5"] = "Once the NM is defeated, check the ??? to exchange the Antique amulet for a Cathedral medallion.", ["|6"] = "Return to Rouva.", ["|7"] = "Head back to Despachiaire for your reward."}},
    [76] = {s = {["|1"] = "Start the quest by talking to Yurim at (J-8) in Tavnazian Safehold on the top floor.", ["|2"] = "Choose a reward, then trade the appropriate base item and chip to Yurim.", ["|3"] = "Speak to Yurim again.", ["|4"] = "Trade the appropriate items to Yurim to complete the quest and receive your reward.", ["|5"] = "Completing the quest once by obtaining any 1 item allows you to trade vices and auras dropped from several HNMs in Lumoria to Meret for a", ["|6"] = "Meret", ["|7"] = "Elemental Gorgets", ["|8"] = "Elemental Obis"}},
    [77] = {s = {["|1"] = "Talk to Enaremand (J-7) (Home Point #3) on the upper level in the Tavnazian Safehold.", ["|2"] = "Head to Mhaura (Kolshushu) to talk with Fyi Chalmwoh at (G-8).", ["|3"] = "Go to Carpenters' Landing where you will fight an Orc NM.", ["|4"] = "Go to (I-10), where you'll find a ??? on a red mushroom near the southwest corner.", ["|5"] = "After you've defeated Bullheaded Grosvez, touch the ??? again to receive Red oil.", ["|6"] = "Go back to the Tavnazian Safehold and talk to Enaremand again for your reward."}},
    [78] = {s = {["|1"] = "Talk with Enaremand (J-7).", ["|2"] = "Talk to Chemioue (J-6).", ["|3"] = "Go to Phomiuna Aqueducts, find a Wooden Ladder at C-9 on the second map, and climb the ladder for a cut-scene.", ["|4"] = "Go to Misareaux Coast and select the ??? at I-6 near the end of the river for the Mire incense.", ["|5"] = "Go to the base of the waterfall at F-4 in Misareaux Coast and select the ??? for a cut-scene.", ["|6"] = "Select the ??? again to spawn the mannequin NM Alsha.", ["|7"] = "Once Alsha is defeated, select the ??? again to obtain Better Humes and Mannequins.", ["|8"] = "Travel to Mhaura and talk to Fyi Chalmwoh who will take the key item then allow you to pose your mannequins for 200 Gil."}},
    [79] = {s = {["|1"] = "Travel to Riverne - Site #A01 and check the Stone Monument at C-7", ["|2"] = "You will receive a cutscene and the Ornamented scroll.", ["|3"] = "Speak to Reinberta in I-8 Bastok Markets.", ["|4"] = "Speak to Mevreauche in E-6 Northern San d'Oria.", ["|5"] = "Head back to and check the Stone Monument in Riverne - Site #A01 for a cutscene.", ["|6"] = "Examine it again to spawn Arcane Phantasm.", ["|7"] = "After defeating the NM, click the Stone Monument once more to complete the quest."}},
    [80] = {s = {["|1"] = "Speak to Tressia (J-6, Third Floor: Patrol HQ)", ["|10"] = "Go to Ondieulix (I-7, Second Floor: Near Home Point #1) for your reward", ["|11"] = "Miledo-Shiraddo also appears in Chameleon Capers.", ["|2"] = "Optional - Speak to Mengrenaux (J-6, Third Floor: Patrol HQ)", ["|3"] = "Optional - Speak to Chemioue (J-6, Third Floor: Patrol HQ)", ["|4"] = "Speak to the following in any order to watch short cutscenes", ["|5"] = "Return to Tressia (J-6)", ["|6"] = "You will be asked to view the data gathered by the other members of the patrol and find out the <pos> where the report was gathered", ["|7"] = "Return to Tressia (J-6) and answer:", ["|8"] = "Follow the trail", ["|9"] = "Return to Tressia (J-6, Third Floor: Patrol HQ)"}},
    [81] = {s = {["|1"] = "Speak with Justinius on the top floor of Tavnazian Safehold to activate the quest and receive a Monarch Linn Patrol Permit.", ["|2"] = "Travel to Monarch Linn.", ["|3"] = "The BCNM is scaled acording to the number of members in the alliance.", ["|4"] = "The Mammet-800 opponents have access to the same abilities as the Mammet-19 Epsilon in Promathia Mission 2-5, though scaled up in", ["|5"] = "The Mammet-800 will change stance when a PC enters the grassy arena.", ["|6"] = "The fight ends as soon as the last Mammet-800 is defeated.", ["|7"] = "Return to Justinius after winning the fight to receive your reward.", ["|8"] = "This quest can be repeated after every Conquest tally."}},
    [82] = {s = {["|1"] = "Speak to Despachiaire to obtain Letter from Shikaree X.", ["|2"] = "Head to Boneyard Gully (fastest teleport is Attohwa Chasm Home Point #1) and select \"Tango with a Tracker\" at the Dark Miasma to enter a", ["|3"] = "There is a 30 minute timer to complete the battle with up to 6 party members.", ["|4"] = "This fight is against:", ["|5"] = "The Shikaree's are both difficult to sleep and the effect will not last long on either of them.", ["|6"] = "They gain TP very quickly and will attempt to Skillchain with each other.", ["|7"] = "Once all three are defeated, the fight will end and you will receive your reward."}},
    [83] = {s = {["|1"] = "Speak to Despachiaire to obtain Letter from Shikaree Y.", ["|2"] = "Head to Boneyard Gully and select \"Requiem of Sin\" at the Dark Miasma to enter a battlefield.", ["|3"] = "There is a 30 minute timer to complete the battle with up to 6 party members.", ["|4"] = "This fight is against:", ["|5"] = "The Shikaree's are difficult to sleep and the effect will not last long on either of them.", ["|6"] = "They gain TP very quickly and will attempt to Skillchain with each other.", ["|7"] = "Once all three are defeated, a treasure chest will spawn with your reward.", ["|8"] = "A Conquest Tally must have taken place after completion of Tango with a Tracker in order to flag this quest. -- Not True as of Aug 2026.The", ["|9"] = "This quest can may be completed once per conquest tally."}},
    [84] = {s = {["|1"] = "Speak with the NPC Owain in Tavnazian Safehold at (H-6) (Homepoint #1) for a cutscene.", ["|2"] = "Choose to participate in voidwatch operations to receive key item Hyacinth stratum abyssite.", ["|3"] = "Defeat the following Voidwatch notorious monsters in Promathia areas", ["|4"] = "Return to Owain to complete the quest and begin the following quest automatically."}},
    [96] = {s = {["|1"] = "Speak to Buffalostalker Dodzbraz to begin the quest.", ["|2"] = "Trade him two Cluster Cores, a fairly common drop from Cluster-type mobs to receive your reward."}},
    [100] = {s = {["|1"] = "Place a Bronze Bed in your Mog House.", ["|2"] = "Wait one earth minute, then speak to the Moogle.", ["|3"] = "Trade your Moogle a Power Bow and a Beetle Ring.", ["|4"] = "When your Moogle returns from his trip after one earth minute, (but somehow never leaving your Mog House), he will give you a Mog Safe that"}},
    [101] = {s = {["|1"] = "Place a Mahogany Bed in your Mog House then speak to the Moogle.", ["|2"] = "Zone out of your Mog House then come back.", ["|3"] = "Return and speak to the Moogle (may need to speak twice).", ["|4"] = "Trade your Moogle a Shrimp Lure and Selbina Butter.", ["|5"] = "When your Moogle returns from his trip after one earth minute, (but somehow never leaving your Mog House), he will give you a Mog Safe that"}},
    [102] = {s = {["|1"] = "Place a Noble's Bed in your Mog House then speak to the Moogle.", ["|2"] = "Zone out of your Mog House then come back.", ["|3"] = "Wait one Earth minute, speak to the Moogle (may need to speak twice), you will receive a cutscene if you have level 7 fame in your home", ["|4"] = "Trade your Moogle a Raptor Mantle and a Wool Hat.", ["|5"] = "When your Moogle returns from his trip after one earth minute, (but somehow never leaving your Mog House), he will give you a Mog Safe that"}},
    [103] = {s = {["|1"] = "Speak to Koblakiq to begin this quest.", ["|2"] = "Trade Koblakiq a Soiled Letter to complete this quest."}},
    [104] = {s = {["|10"] = "After receiving Glittering fragment, head to Beadeaux.", ["|11"] = "After going through the exit at (F-8), you will once again be above ground.", ["|12"] = "After the fight, talk to Ge'Fhu Yagudoeye again, and you'll receive a short cutscene.", ["|4"] = "After completing Missionary Moblin, talk to Koblakiq at (H-11) to begin the quest.", ["|5"] = "Obtain an Arnica Root if you haven't already.", ["|6"] = "Head to Castle Oztroja and go to the Brass Door at (I-8).", ["|7"] = "On the next map, head to (G-7) and go through the exit.", ["|8"] = "Trade the Arnica Root to Daa Bola the Seer.", ["|9"] = "After speaking to the yagudo, head back to Oldton Movalpolos and speak with Koblakiq."}},
    [105] = {s = {["|2"] = "Speak to Koblakiq to begin this quest.", ["|3"] = "Head to Castle Zvahl Baileys and fight Blood Demons and Demon Generals until you obtain a Demon Pen.", ["|4"] = "Trade the Demon Pen to Koblakiq.", ["|5"] = "Wait 1 earth minute, then speak to Koblakiq again.", ["|6"] = "Return to Castle Zvahl Baileys and check the ??? at (I-8 behind the gate where Dark Spark spawns) to spawn Marquis Andrealphus, Demon", ["|7"] = "Examine the ??? again after Marquis Andrealphus is defeated to obtain Zeelozok's earplug.", ["|8"] = "Return to Koblakiq to complete this quest."}},
    [108] = {s = {["|1"] = "Enter Altar Room for a cutscene that starts this quest.", ["|10"] = "Equip Tsoo's Headgear, zone out to the south of Altar Room and then back into the zone for a cutscene and a Gold Beastcoin.", ["|2"] = "Speak to Ponono, Windurst Woods (G-12) for a cutscene.", ["|3"] = "Trade Ponono a Velvet Cloth, Rainbow Cloth, and 10,000 gil.", ["|4"] = "Wait until the next game day to talk to Ponono again who will give you Yagudo Cutting and instructions on how to craft it into a Yagudo", ["|5"] = "Synthesize a Yagudo Headgear:", ["|6"] = "Return Altar Room while wearing your Yagudo Headgear for a cutscene.", ["|7"] = "Check the Stone Lid while wearing the Yagudo Headgear to spawn the following NM's:", ["|8"] = "Once Yagudo Avatar is defeated, check the Stone Lid again while having the Yagudo Headgear equipped for a cutscene.", ["|9"] = "Trade your Yagudo Headgear to the Stone Lid to have it replaced by Tsoo's Headgear."}},
    [204] = {s = {["|1"] = "Upon reaching level 2 in Monster Rearing from obtaining the key item \"Sakura and the Magic Spoon\" zone into your Mog Garden.", ["|2"] = "Trade Chacharoon a Gold Beastcoin to complete the quest.", ["|3"] = "You'll unlock the ability to \"Discuss a cheering effect.\" with Chacharoon."}},
    [205] = {s = {["|1"] = "Care for monsters an additional 5 times in order to purchase \"Sakura and the Fountain\" from Zenicca or a Skipper Moogle.", ["|2"] = "After purchasing the key item, enter your newly expanded Mog Garden area which features the Rearing Grounds.", ["|3"] = "Speak to Chacharoon in the newly open area to complete the quest and gain access to use the Trust Magic: Chacharoon."}},
    [206] = {s = {["|1"] = "Continue monster rearing and purchase the key item \"Sakura's Excellent Adventure\" from Zenicca or a Skipper Moogle.", ["|2"] = "Enter your Mog Garden for a cutscene", ["|3"] = "Trade 12 Crayfish to your Green Thumb Moogle to complete the quest.", ["|4"] = "Note: Once the quest is activated, you will automatically receive the rank 5 promotion, and immediately be able to raise three simultaneous"}},
    [207] = {s = {["|1"] = "Continue monster rearing and purchase the key item \"Sakura and the Holy Grail\"(Interact ~100 times) from Zenicca or a Skipper Moogle.", ["|2"] = "Enter your Mog Garden for a cutscene", ["|3"] = "Head to Muckvix's Junk Shop in Lower Jeuno at (H-9) and speak to Stinknix for a cutscene and the KI: Chacharoon's sack of supplies.", ["|4"] = "Speak to Chacharoon not in the main area of your Mog Garden but in the Rearing Grounds for a cutscene and your rewards."}},
    [1039] = {s = {["|1"] = "Visit either NPC outside of the Mog House entrance in Western Adoulin or Eastern Adoulin to access your Mog Garden.", ["|2"] = "Upon zoning in, your Green Thumb Moogle will give you a GPS crystal, and instruct you to harvest from the nearby Garden Furrow.", ["|3"] = "After harvesting from the Garden Furrow, report back to the Green Thumb Moogle for your reward."}},
}
